'use client';

import { useEffect, useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { fetchApi, api } from '@/lib/api';
import { Clock, CheckCircle, XCircle, Edit, Trash2 } from 'lucide-react';
import { toast } from 'sonner';

type MyPost = {
  id: string;
  title: string;
  description: string;
  price: number;
  status: 'PENDING' | 'APPROVED' | 'REJECT';
  category: string;
  location: string;
  images: string[];
  createdAt: string;
};

export default function MyPostsPage() {
  const [posts, setPosts] = useState<MyPost[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchMyPosts = async () => {
    try {
      const data = await fetchApi(`${api.items}/my-items`);
      const list = data?.data?.items || data?.items || [];
      setPosts(list);
    } catch (e) {
      console.error('Failed to fetch my posts:', e);
      setPosts([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMyPosts();
  }, []);

  const getStatusBadge = (status: string) => {
    if (status === 'PENDING') {
      return <Badge className="bg-yellow-100 text-yellow-800"><Clock className="w-3 h-3 mr-1" /> Pending</Badge>;
    }
    if (status === 'APPROVED') {
      return <Badge className="bg-green-100 text-green-800"><CheckCircle className="w-3 h-3 mr-1" /> Approved</Badge>;
    }
    return <Badge className="bg-red-100 text-red-800"><XCircle className="w-3 h-3 mr-1" /> Rejected</Badge>;
  };

  if (loading) {
    return <div className="p-8">Loading your posts...</div>;
  }

  return (
    <div className="space-y-6 p-6">
      <div>
        <h1 className="text-3xl font-bold">My Posts</h1>
        <p className="text-gray-600 mt-1">View and track the status of your product listings</p>
      </div>

      {posts.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <p className="text-gray-500">You haven't posted any items yet.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {posts.map((post) => (
            <Card key={post.id} className="overflow-hidden flex flex-col">
              {/* Image */}
              <div className="relative h-48 bg-gray-100">
                {post.images?.length > 0 ? (
                  <img
                    src={post.images[0]}
                    alt={post.title}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-400">
                    No Image
                  </div>
                )}
                <div className="absolute top-3 right-3">
                  {getStatusBadge(post.status)}
                </div>
              </div>

              <CardContent className="flex-1 flex flex-col p-4">
                <div className="flex-1">
                  <h3 className="font-semibold text-lg mb-1 line-clamp-2">{post.title}</h3>
                  <p className="text-sm text-gray-500 mb-2">{post.category} • {post.location}</p>
                  <p className="text-gray-600 text-sm line-clamp-3 mb-3">{post.description}</p>
                </div>

                <div className="mt-auto">
                  <div className="flex items-center justify-between mb-3">
                    <span className="font-bold text-xl">৳{post.price}</span>
                    <span className="text-xs text-gray-500">
                      {new Date(post.createdAt).toLocaleDateString()}
                    </span>
                  </div>

                  {/* Actions */}
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      className="flex-1"
                      onClick={() => {
                        // TODO: Open edit modal (can reuse logic from items page)
                        toast.info('Edit functionality coming soon');
                      }}
                    >
                      <Edit className="w-4 h-4 mr-1" /> Edit
                    </Button>
                    <Button
                      variant="destructive"
                      size="sm"
                      className="flex-1"
                      onClick={async () => {
                        if (!confirm('Delete this post?')) return;
                        try {
                          await fetchApi(`${api.items}/${post.id}`, { method: 'DELETE' });
                          toast.success('Post deleted');
                          fetchMyPosts();
                        } catch (err) {
                          toast.error('Failed to delete');
                        }
                      }}
                    >
                      <Trash2 className="w-4 h-4 mr-1" /> Delete
                    </Button>
                  </div>

                  {post.status === 'PENDING' && (
                    <p className="mt-3 text-xs text-yellow-600">
                      Under admin review
                    </p>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
